// --- CONFIGURACIÓN DE UMBRALES (Negocio Local) ---
const UMBRALES = {
  COSTE_POR_CONVERSACION_MAX: 4.00,
  COSTE_POR_LEAD_MAX: 6.00,
  CTR_MIN: 1.5,
  // CPM_MAX: 50.00 // Umbral de ejemplo si decides usarlo en el futuro
};

// --- LÓGICA DEL NODO ---

// Obtiene el item de entrada con los datos del anuncio
const ad = $input.item.json;

// --- Módulo de Presupuesto Diario ---
let daily_budget_formatted = "N/A";
try {
  // Obtiene el presupuesto desde el nodo HTTP Request
  const rawBudget = $('Get daily budget').first().json.daily_budget;
  if (rawBudget) {
    // Formatea el número: 1500 -> 15.00
    daily_budget_formatted = (parseInt(rawBudget) / 100).toFixed(2);
  }
} catch (error) {
  // No hace nada si el nodo o el dato no existen, para evitar que el workflow falle.
}
ad.daily_budget_formatted = daily_budget_formatted;


// Variables para el análisis
const motivosParaParar = [];
let leadInfo = null;


// --- Análisis de Métricas Principales ---

// 1. Análisis de CTR (Click-Through Rate)
if (ad.ctr) {
    const ctr = parseFloat(ad.ctr);
    if (ctr < UMBRALES.CTR_MIN) {
        motivosParaParar.push(`CTR bajo (${ctr.toFixed(2)}%)`);
    }
}


// 2. Análisis de Costo por Acción (Conversaciones y Leads)

// CASO A: El input es un array 'cost_per_action_type'
if (ad.cost_per_action_type && ad.cost_per_action_type.length > 0) {
  for (const action of ad.cost_per_action_type) {
    const costValue = parseFloat(action.value);

    // Análisis de Costo por Conversación
    if (action.action_type === 'onsite_conversion.messaging_conversation_started_7d') {
      if (costValue > UMBRALES.COSTE_POR_CONVERSACION_MAX) {
        motivosParaParar.push(`Costo por Conversación alto ($${costValue.toFixed(2)})`);
      }
    }

    // --- Módulo de Análisis de Leads ---
    if (action.action_type === 'lead') {
      leadInfo = {
        ad_id: ad.ad_id,
        account_name: ad.account_name,
        costo_lead: costValue.toFixed(2)
      };
      if (costValue > UMBRALES.COSTE_POR_LEAD_MAX) {
        motivosParaParar.push(`Costo por Lead alto ($${costValue.toFixed(2)})`);
      }
    }
    // --- Fin del Módulo de Leads ---
  }
}
// CASO B: El input es un objeto 'cost_per_result'
else if (ad.cost_per_result && ad.cost_per_result.value) {
    const costValue = parseFloat(ad.cost_per_result.value);
    const actionType = ad.cost_per_result.indicador || "";

    // Análisis de Costo por Conversación
    if (actionType.includes('onsite_conversion.messaging_conversation_started_7d')) {
        if (costValue > UMBRALES.COSTE_POR_CONVERSACION_MAX) {
            motivosParaParar.push(`Costo por Conversación alto ($${costValue.toFixed(2)})`);
        }
    }

    // --- Módulo de Análisis de Leads ---
    if (actionType.includes('lead')) {
        leadInfo = {
            ad_id: ad.ad_id,
            account_name: ad.account_name,
            costo_lead: costValue.toFixed(2)
        };
        if (costValue > UMBRALES.COSTE_POR_LEAD_MAX) {
            motivosParaParar.push(`Costo por Lead alto ($${costValue.toFixed(2)})`);
        }
    }
    // --- Fin del Módulo de Leads ---
}


// --- Decisión Final ---

if (motivosParaParar.length > 0) {
  ad.estado = 'PARAR ANUNCIO';
  ad.motivo = motivosParaParar.join(', ');
} else {
  ad.estado = 'OK';
  ad.motivo = 'Rendimiento dentro de los umbrales.';
}

if (leadInfo) {
  ad.lead_info = leadInfo;
}

// Devuelve el objeto original del anuncio, pero con los nuevos campos añadidos.
return ad;

